alias ClimbOntario.Catalogue.Import

tz="America/Toronto"
put! = fn a,s -> case Import.put_listing(a,s) do {:ok,l}->IO.puts("repaired #{l.id}: #{length(l.occurrences)} occurrences"); {:error,c}->IO.inspect(c);raise "repair failed" end end
src=fn u->%{sources: u,checked_on: ~D[2026-09-06],published: false,confidence: "confirmed"} end
o=fn d,s,e->%{date: d,start_time: s,end_time: e,timezone: tz} end
base=%{venue_id: 12,timezone: tz,location_kind: "venue",published: false}
put!.(Map.merge(base,%{id: 32,title: "School of Rock",kind: "class",summary: "Structured introductory youth climbing programme for ages 8–14.",schedule_kind: "unscheduled",audience: ["youth"],ages: "8–14",link: "https://www.upthebloc.com/kids",link_kind: "event"}|>Map.merge(src.( ["https://www.upthebloc.com/kids","https://www.upthebloc.com/programs"]))),:preserve)
put!.(Map.merge(base,%{id: 33,title: "Youth Competitive Team — 2026–2027",kind: "class",summary: "Youth competitive climbing team training in movement, fitness and problem-solving.",schedule_kind: "unscheduled",audience: ["youth"],ages: "Youth",link: "https://www.upthebloc.com/kids",link_kind: "event"}|>Map.merge(src.( ["https://www.upthebloc.com/kids"]))),:preserve)
put!.(Map.merge(base,%{id: 34,title: "Bouldering 201",kind: "class",summary: "Six-week bouldering technique course for climbers aged 14 and older.",schedule_kind: "unscheduled",audience: ["adult"],ages: "14+",link: "https://www.upthebloc.com/classes",link_kind: "registration"}|>Map.merge(src.( ["https://www.upthebloc.com/classes","https://app.rockgympro.com/b/?bo=1adfe175145a4f7c8df938339b1eada7"]))),:preserve)
put!.(Map.merge(base,%{id: 35,title: "Summer SENDoff — August 2026",kind: "social",summary: "Summer bouldering party with community activities and side quests.",schedule_kind: "one_off",start_date: ~D[2026-08-25],end_date: ~D[2026-08-25],start_time: ~T[18:00:00],end_time: ~T[23:00:00],audience: ["family"],link: "https://www.instagram.com/upthebloc/p/DcOsc9DkbuC/",link_kind: "event"}|>Map.merge(src.( ["https://www.instagram.com/upthebloc/p/DcOsc9DkbuC/"]))),[o.(~D[2026-08-25],~T[18:00:00],~T[23:00:00])])
put!.(Map.merge(base,%{id: 36,title: "October 2026 event — name unannounced",kind: "social",summary: "An upcoming community event announced for October 2026.",schedule_kind: "unscheduled",audience: ["family"],link: "https://www.instagram.com/upthebloc/reel/DcjTy1IpX2y/",link_kind: "event"}|>Map.merge(src.( ["https://www.instagram.com/upthebloc/reel/DcjTy1IpX2y/"]))),:preserve)
starts=for d<-Date.range(~D[2026-09-07],~D[2026-09-13]), t<- [~T[16:00:00],~T[17:00:00],~T[18:00:00],~T[19:00:00],~T[20:00:00]], Date.day_of_week(d)<=5, do: o.(d,t,Time.add(t,270))
weekend=for d<- [~D[2026-09-12],~D[2026-09-13]], t<- [~T[11:00:00],~T[12:00:00],~T[13:00:00],~T[14:00:00]], do: o.(d,t,Time.add(t,270))
put!.(Map.merge(base,%{id: 268,title: "Bouldering 101 — introductory classes",kind: "class",summary: "Instructor-led introductory bouldering classes covering movement technique, route reading and safety.",schedule_kind: "recurring",schedule_note: "Thirty-three September 7–13 starts are confirmed; later September markers were not individually inspected.",audience: ["adult"],link: "https://app.rockgympro.com/b/?bo=e18b603a702746588749475b42e45907",link_kind: "registration"}|>Map.merge(src.( ["https://www.upthebloc.com/classes","https://app.rockgympro.com/b/?bo=e18b603a702746588749475b42e45907"]))),starts++weekend)
